    protected void createGenModelAnnotations() {
        String source = "http://www.eclipse.org/emf/2002/GenModel";
        this.addAnnotation((ENamedElement)this.canTpAddressingFormatTypeEEnum, source, new String[]{"documentation", "Declares which communication addressing mode is supported.\r\n"});
        this.addAnnotation((ENamedElement)this.canTpAddressingFormatTypeEEnum.getELiterals().get(0), source, new String[]{"documentation", "To use normal addressing format."});
        this.addAnnotation((ENamedElement)this.canTpAddressingFormatTypeEEnum.getELiterals().get(1), source, new String[]{"documentation", "To use extended addressing format."});
        this.addAnnotation((ENamedElement)this.canTpAddressingFormatTypeEEnum.getELiterals().get(2), source, new String[]{"documentation", "To use mixed addressing format.\r\n"});
        this.addAnnotation((ENamedElement)this.canTpChannelModeTypeEEnum.getELiterals().get(0), source, new String[]{"documentation", "half duplex channel mode\r\n"});
        this.addAnnotation((ENamedElement)this.canTpChannelModeTypeEEnum.getELiterals().get(1), source, new String[]{"documentation", "full duplex channel mode\r\n"});
        this.addAnnotation((ENamedElement)this.canTpConnectionChannelEClass, source, new String[]{"documentation", "A connection channel represents an internal path for the transmission or reception of a Pdu via CanTp\r\nand describes the the sender and the receiver of this particular communication.\r\n\r\nThe CanTp module routes a Pdu through the connection channel "});
        this.addAnnotation((ENamedElement)this.getCanTpConnectionChannel_AddressingFormat(), source, new String[]{"documentation", "Declares which communication addressing mode is supported."});
        this.addAnnotation((ENamedElement)this.getCanTpConnectionChannel_BlockSize(), source, new String[]{"documentation", "The maximum number of N-PDUs the CanTp receiver allows the sender to send, before waiting for an authorization to continue transmission of the following N-PDUs. For further details on this parameter value see ISO 15765-2 specification.\r\n\r\nNote: For reasons of buffer length, the CAN Transport Layer can adapt the BS value within the limit of this maximum BS"});
        this.addAnnotation((ENamedElement)this.getCanTpConnectionChannel_ChannelModeType(), source, new String[]{"documentation", "The CAN Transport Layer supports half and full duplex channel modes.\r\n"});
        this.addAnnotation((ENamedElement)this.getCanTpConnectionChannel_DataPdu(), source, new String[]{"documentation", "Reference to an NPdu (Single Frame, First Frame or Consecutive Frame).\r\n\r\nThe Single Frame network protocol data unit (SF N_PDU) shall be sent out by the sending network entity and can be received by one or multiple receiving network entities.\r\nThe Single Frame (SF N_PDU) shall be sent out to transfer a service data unit that can be transferred via a single service request to the data link layer. This network protocol data unit shall be sent to transfer unsegmented messages.\r\n\r\nThe First Frame network protocol data unit (FF N_PDU) identifies the first network protocol data unit (N_PDU) of a segmented message transmitted by a network sending entity and received by a receiving network entity. \r\n\r\nThe Consecutive Frame network protocol data unit (CF N_PDU) transfers segments (N_Data) of the service data unit message data (<MessageData>). All network protocol data units (N_PDUs) transmitted by the sending entity after the First Frame network protocol data unit (FF N_PDU) shall be encoded as Consecutive Frames network protocol data units (CF N_PDUs)."});
        this.addAnnotation((ENamedElement)this.getCanTpConnectionChannel_FlowControlPdu(), source, new String[]{"documentation", "Reference to the  Flow Control NPdu.\r\n\r\nThe Flow Control network protocol data unit (FC N_PDU) is identified by the Flow Control protocol control information (FC N_PCI). The Flow Control network protocol data unit (FC N_PDU) instructs a sending network entity to start, stop or resume transmission of CF N_PDUs. The Flow Control network protocol data unit shall be sent by the receiving network layer entity to the sending network layer entity, when ready to receive more data, after correct reception of:\r\n\r\na) First Frame network protocol data unit (FF N_PDU) \r\nb) the last Consecutive Frame network protocol data unit (CF N_PDU) of a block of Consecutive Frames (CF N_PDU) if further Consecutive Frame network protocol data unit (CF N_PDU) need(s) to be sent.\r\n"});
        this.addAnnotation((ENamedElement)this.getCanTpConnectionChannel_MinimumSeparationTime(), source, new String[]{"documentation", "This attribute defines the minimum amount of time (separation Time) between two succeeding CFs. Specified in seconds."});
        this.addAnnotation((ENamedElement)this.getCanTpConnectionChannel_MulticastAddressing(), source, new String[]{"documentation", "Specifies the communication type:\r\n\r\ntrue: 1:n communication (Functional)\r\nfalse: 1:1 communication (Physical)"});
        this.addAnnotation((ENamedElement)this.getCanTpConnectionChannel_Multicast(), source, new String[]{"documentation", "TP address for 1:n connections.\r\n"});
        this.addAnnotation((ENamedElement)this.getCanTpConnectionChannel_PaddingActivation(), source, new String[]{"documentation", "Defines if the receive frame uses padding or not.\r\n\r\ntrue:\r\nThe N-PDU received uses padding for SF, FC and the last CF. (N-PDU length is always 8 bytes)\r\n\r\nfalse:\r\nThe N-PDU received does not use padding for SF, CF and the last CF. (N-PDU length is dynamic)"});
        this.addAnnotation((ENamedElement)this.getCanTpConnectionChannel_Source(), source, new String[]{"documentation", "The source of the TP connection."});
        this.addAnnotation((ENamedElement)this.getCanTpConnectionChannel_TaType(), source, new String[]{"documentation", "Network Target Address type."});
        this.addAnnotation((ENamedElement)this.getCanTpConnectionChannel_Targets(), source, new String[]{"documentation", "The target of the TP connection.\r\n"});
        this.addAnnotation((ENamedElement)this.getCanTpConnectionChannel_TimeoutAs(), source, new String[]{"documentation", "Value in second of the N_As timeout. N_As is the time for transmission of a CAN frame (any N_PDU) on the part of the sender."});
        this.addAnnotation((ENamedElement)this.getCanTpConnectionChannel_TimeoutBr(), source, new String[]{"documentation", "N_Br is the elapsed time (in seconds) between the receiving indication of a FF or CF or the transmit confirmation of a FC, until the transmit request of the next FC."});
        this.addAnnotation((ENamedElement)this.getCanTpConnectionChannel_TimeoutBs(), source, new String[]{"documentation", "Value in seconds of the N_Bs timeout. N_Bs is the time of transmission until reception of the next Flow Control N_PDU."});
        this.addAnnotation((ENamedElement)this.getCanTpConnectionChannel_TimeoutCr(), source, new String[]{"documentation", "Value in seconds of the N_Cr timeout. N_Cr is the time until reception of the next Consecutive Frame N_PDU."});
        this.addAnnotation((ENamedElement)this.getCanTpConnectionChannel_TimeoutCs(), source, new String[]{"documentation", "N_Cs is the time (in seconds) which elapses between the transmit request of a CF N-PDU until the transmit request of the next CF N-PDU."});
        this.addAnnotation((ENamedElement)this.getCanTpConnectionChannel_TpSdu(), source, new String[]{"documentation", "Reference to the IPdu that is segmented by the Transport Protocol. \r\n\r\nTo support the low-level routing of NPdu's the NPdu is a specialization of an IPdu. More details can be found in the NPdu class description. Nevertheless the CanTpConnection must not reference a NPdu with this tpSdu reference. "});
        this.addAnnotation((ENamedElement)this.networkTargetAddressTypeEEnum, source, new String[]{"documentation", "Network Target Address type (see ISO 15765-2)."});
        this.addAnnotation((ENamedElement)this.networkTargetAddressTypeEEnum.getELiterals().get(0), source, new String[]{"documentation", "Physical request type"});
        this.addAnnotation((ENamedElement)this.networkTargetAddressTypeEEnum.getELiterals().get(1), source, new String[]{"documentation", "Functional request type"});
        this.addAnnotation((ENamedElement)this.canTpNodeEClass, source, new String[]{"documentation", "TP Node (Sender or Receiver) provides the TP Address and the connection to the Topology description.\r\n"});
        this.addAnnotation((ENamedElement)this.getCanTpNode_RxWftMax(), source, new String[]{"documentation", "This parameter indicates how many Flow Control wait N-PDUs can be consecutively transmitted by the receiver. "});
        this.addAnnotation((ENamedElement)this.getCanTpNode_TimeoutAr(), source, new String[]{"documentation", "Value in seconds of the N_Ar timeout. N_Ar is the time for transmission of a CAN frame (any N_PDU) on the receiver side."});
        this.addAnnotation((ENamedElement)this.tpNodeEClass, source, new String[]{"documentation", "TP Node (Sender or Receiver) provides the TP Address and the connection to the Topology description. \r\n"});
        this.addAnnotation((ENamedElement)this.getTpNode_Connectors(), source, new String[]{"documentation", "Asscociation  to one or more physical connectors (max number of connectors for FlexRay: 2).\r\n\r\nIn a System Description this reference is mandatory. In an ECU Extract this reference is optional (references to ECUs that are not part of the ECU Extract shall be avoided).    \r\n"});
        this.addAnnotation((ENamedElement)this.getTpNode_TpAddress(), source, new String[]{"documentation", "Reference to the TP Address that is used by the TpNode. This reference is optional in case that the multicast TP Address is used (reference from TpConnection)."});
        this.addAnnotation((ENamedElement)this.tpAddressEClass, source, new String[]{"documentation", "An ECUs TP address on the referenced channel. This represents the diagnostic Address. \r\n"});
        this.addAnnotation((ENamedElement)this.getTpAddress_TpAddress(), source, new String[]{"documentation", "An ECUs TP address on the referenced channel. This represents the diagnostic Address. "});
        this.addAnnotation((ENamedElement)this.flexrayIsoTpConnectionEClass, source, new String[]{"documentation", "A connection identifies the sender and the receiver of this particular communication. The FlexRayIsoTp module routes a Pdu through this connection. \r\n\r\nIn a System Description the references to the PduPools are mandatory. In an ECU Extract these references can be optional:\r\nOn unicast connections these references are always mandatory.\r\nOn multicast the txPduPool is mandatory on the sender side. The rxPduPool is mandatory on the receiver side. On Gateway ECUs both references are mandatory. \r\n"});
        this.addAnnotation((ENamedElement)this.getFlexrayIsoTpConnection_BandwidthLimitation(), source, new String[]{"documentation", "Specifies whether the connection requires a  bandwidth limitation or not.\r\n"});
        this.addAnnotation((ENamedElement)this.getFlexrayIsoTpConnection_DirectTpSdu(), source, new String[]{"documentation", "Reference to the IPdu that is segmented by the Transport Protocol. \r\n\r\nTo support the low-level routing of NPdu's the NPdu is a specialization of an IPdu. More details can be found in the NPdu class description. Nevertheless the FlexrayIsoTpConnection must not reference a NPdu with this tpSdu reference. \r\n"});
        this.addAnnotation((ENamedElement)this.getFlexrayIsoTpConnection_Multicast(), source, new String[]{"documentation", "TP address for 1:n connections."});
        this.addAnnotation((ENamedElement)this.getFlexrayIsoTpConnection_Receivers(), source, new String[]{"documentation", "The target of the TP connection.\r\n"});
        this.addAnnotation((ENamedElement)this.getFlexrayIsoTpConnection_ReversedTpSdu(), source, new String[]{"documentation", "Reference to the IPdu that is segmented by the Transport Protocol. If support of both sending and receiving is used, this association references the IPdu used for the additional second direction.\r\n\r\nTo support the low-level routing of NPdu's the NPdu is a specialization of an IPdu. More details can be found in the NPdu class description. Nevertheless the FlexrayIsoTpConnection must not reference a NPdu with this tpSdu reference.\r\n"});
        this.addAnnotation((ENamedElement)this.getFlexrayIsoTpConnection_RxPduPool(), source, new String[]{"documentation", "A connection has a reference to a set of NPdus (FrTpRxPduPool) which are defined for receiving data via this particular connection."});
        this.addAnnotation((ENamedElement)this.getFlexrayIsoTpConnection_TpConnectionControl(), source, new String[]{"documentation", "Reference to the connection control."});
        this.addAnnotation((ENamedElement)this.getFlexrayIsoTpConnection_Transmitter(), source, new String[]{"documentation", "The source of the TP connection.\r\n"});
        this.addAnnotation((ENamedElement)this.getFlexrayIsoTpConnection_TxPduPool(), source, new String[]{"documentation", "A connection has a reference to a set of NPdus (FrTpTxPduPool) which are defined for sending data via this particular connection."});
        this.addAnnotation((ENamedElement)this.flexrayIsoTpPduPoolEClass, source, new String[]{"documentation", "FlexrayTpPduPool is a set of N-PDUs which are defined for FrTp sending or receiving purpose.\r\n"});
        this.addAnnotation((ENamedElement)this.getFlexrayIsoTpPduPool_NPdus(), source, new String[]{"documentation", "Reference to NPdus that are part of the PduPool. \r\n"});
        this.addAnnotation((ENamedElement)this.flexrayIsoTpNodeEClass, source, new String[]{"documentation", "TP Node (Sender or Receiver) provides the TP Address and the connection to the Topology description. \r\n"});
        this.addAnnotation((ENamedElement)this.flexrayIsoTpConnectionControlEClass, source, new String[]{"documentation", "Configuration parameters to control a FlexRay TP connection.\r\n"});
        this.addAnnotation((ENamedElement)this.getFlexrayIsoTpConnectionControl_AckType(), source, new String[]{"documentation", "This parameter defines the type of acknowledgement which is used for the specific channel. For FlexrayIsoTp only noAck and ackWithRt shall be used. \r\n"});
        this.addAnnotation((ENamedElement)this.getFlexrayIsoTpConnectionControl_MaxAr(), source, new String[]{"documentation", "This parameter defines the maximum number of trying to send a frame when a TIMEOUT AR occurs (depending on whether retry is configured).\r\n"});
        this.addAnnotation((ENamedElement)this.getFlexrayIsoTpConnectionControl_MaxAs(), source, new String[]{"documentation", "This parameter defines the maximum number of trying to send a frame when a TIMEOUT AS occurs (depending on whether retry is configured)\r\n"});
        this.addAnnotation((ENamedElement)this.getFlexrayIsoTpConnectionControl_MaxBufferSize(), source, new String[]{"documentation", "This parameter is only relevant when having retry activated. It limits the maximal buffer size the FrTp can choose in order to limit the amount of Tx buffer that will be requested at the sender side in a segmented transfer.\r\n"});
        this.addAnnotation((ENamedElement)this.getFlexrayIsoTpConnectionControl_MaxFcWait(), source, new String[]{"documentation", "This attribute defines the maximum number of FlowControl N-PDUs with FlowState \"WAIT\".\r\n"});
        this.addAnnotation((ENamedElement)this.getFlexrayIsoTpConnectionControl_MaxFrIf(), source, new String[]{"documentation", "This parameter defines the maximum number of trying to send a frame when the FrIf returns an error\r\n"});
        this.addAnnotation((ENamedElement)this.getFlexrayIsoTpConnectionControl_MaxNumberOfNpduPerCycle(), source, new String[]{"documentation", "This parameter limits the number of N-Pdus the sender is allowed to transmit within a FlexRay cycle.\r\n"});
        this.addAnnotation((ENamedElement)this.getFlexrayIsoTpConnectionControl_MaxRetries(), source, new String[]{"documentation", "This parameter defines the maximum number of retries (if retry is configured for the particular channel).\r\n"});
        this.addAnnotation((ENamedElement)this.getFlexrayIsoTpConnectionControl_SeparationCycleExponent(), source, new String[]{"documentation", "Exponent to calculate the minimum number of \"Separation Cycles\" the sender has to wait for the next transmission of an FrTp N-Pdu.\r\n"});
        this.addAnnotation((ENamedElement)this.getFlexrayIsoTpConnectionControl_TimeBr(), source, new String[]{"documentation", "Time (in seconds) until transmission of the next FlowControl N-PDU.\r\n"});
        this.addAnnotation((ENamedElement)this.getFlexrayIsoTpConnectionControl_TimeBuffer(), source, new String[]{"documentation", "This parameter defines the time of waiting for the next try to get a Tx or Rx buffer.\r\n\r\nThis parameter is equivalent to the temporal distance between two FC.WT N-Pdus in case the buffer request returns busy.\r\n\r\nSpecified in seconds.\r\n"});
        this.addAnnotation((ENamedElement)this.getFlexrayIsoTpConnectionControl_TimeFrIf(), source, new String[]{"documentation", "This parameter defines the time of waiting for the next try to send. Specified in seconds.\r\n"});
        this.addAnnotation((ENamedElement)this.getFlexrayIsoTpConnectionControl_TimeoutAr(), source, new String[]{"documentation", "This parameter states the timeout between the PDU transmit request of the Transport Layer to the FlexRay Interface and the corresponding confirmation of the FlexRay Interface on the receiver side (for FC or AF). Specified in seconds.\r\n"});
        this.addAnnotation((ENamedElement)this.getFlexrayIsoTpConnectionControl_TimeoutAs(), source, new String[]{"documentation", "This attribute states the timeout between the PDU transmit request for the first PDU of the group used in the current connection of the Transport Layer to the FlexRay Interface and the corresponding confirmation of the FlexRay Interface (when having sent the last PDU of the group used in this connection) on the sender side (SF-x, FF-x, CF or FC (in case of Transmit Cancellation)). Specified in seconds.\r\n"});
        this.addAnnotation((ENamedElement)this.getFlexrayIsoTpConnectionControl_TimeoutBs(), source, new String[]{"documentation", "This parameter defines the timeout in seconds for waiting for an FC or AF on the sender side in a 1:1 connection.\r\n"});
        this.addAnnotation((ENamedElement)this.getFlexrayIsoTpConnectionControl_TimeoutCr(), source, new String[]{"documentation", "This parameter defines the timeout value in seconds for waiting for a CF or FF-x (in case of retry) after receiving the last CF or after sending an FC or AF on the receiver side. Specified in seconds.\r\n"});
        this.addAnnotation((ENamedElement)this.tpAckTypeEEnum, source, new String[]{"documentation", "Type of Acknowledgement."});
        this.addAnnotation((ENamedElement)this.tpAckTypeEEnum.getELiterals().get(0), source, new String[]{"documentation", "No acknowledgement."});
        this.addAnnotation((ENamedElement)this.tpAckTypeEEnum.getELiterals().get(1), source, new String[]{"documentation", "Acknowledgement without retry."});
        this.addAnnotation((ENamedElement)this.tpAckTypeEEnum.getELiterals().get(2), source, new String[]{"documentation", "Acknowledgement with retry."});
        this.addAnnotation((ENamedElement)this.flexrayIsoTpEcuEClass, source, new String[]{"documentation", "ECU specific TP configuration parameters. Each TpEcu element has a reference to exactly one ECUInstance in the topology. \r\n"});
        this.addAnnotation((ENamedElement)this.getFlexrayIsoTpEcu_CycleTimeMainFunction(), source, new String[]{"documentation", "The period between successive calls to the Main Function of the AUTOSAR TP. Specified in seconds.\r\n"});
        this.addAnnotation((ENamedElement)this.getFlexrayIsoTpEcu_EcuInstance(), source, new String[]{"documentation", "Connection to the ECUInstance in the Topology.\r\n"});
        this.addAnnotation((ENamedElement)this.getFlexrayIsoTpEcu_FullDuplexEnabled(), source, new String[]{"documentation", "The full duplex mechanisms is enabled if this attribute is set to true. Otherwise half duplex is enabled. \r\n"});
        this.addAnnotation((ENamedElement)this.flexrayTpChannelEClass, source, new String[]{"documentation", "A channel is a group of connections sharing several properties.\r\n\r\nThe FlexRay Transport Layer supports several channels. These channels can work concurrently, thus each of them requires its own state machine and management data structures and its own PDU-IDs."});
        this.addAnnotation((ENamedElement)this.getFlexrayTpChannel_AckType(), source, new String[]{"documentation", "Type of Acknowledgement."});
        this.addAnnotation((ENamedElement)this.getFlexrayTpChannel_ExtendedAddressing(), source, new String[]{"documentation", "Adressing Type of this connection:\r\ntrue: Two Bytes\r\nfalse: One Byte"});
        this.addAnnotation((ENamedElement)this.getFlexrayTpChannel_FlowControlPdu(), source, new String[]{"documentation", "Reference to the  Flow Control NPdu.\r\n\r\nThe Flow Control network protocol data unit (FC N_PDU) is identified by the Flow Control protocol control information (FC N_PCI). The Flow Control network protocol data unit (FC N_PDU) instructs a sending network entity to start, stop or resume transmission of CF N_PDUs. The Flow Control network protocol data unit shall be sent by the receiving network layer entity to the sending network layer entity, when ready to receive more data, after correct reception of:"});
        this.addAnnotation((ENamedElement)this.getFlexrayTpChannel_MaxAr(), source, new String[]{"documentation", "This parameter defines the maximum number of trying to send a frame when a TIMEOUT AR occurs (depending on whether retry is configured)."});
        this.addAnnotation((ENamedElement)this.getFlexrayTpChannel_MaxAs(), source, new String[]{"documentation", "This parameter defines the maximum number of trying to send a frame when a TIMEOUT AS occurs (depending on whether retry is configured)."});
        this.addAnnotation((ENamedElement)this.getFlexrayTpChannel_MaxBs(), source, new String[]{"documentation", "This parameter is only relevant when having retry activated. It limits the maximal block size the FrTp can choose in order to limit the amount of Tx buffer that will be requested at the sender side in a segmented transfer."});
        this.addAnnotation((ENamedElement)this.getFlexrayTpChannel_MaxBufferRequest(), source, new String[]{"documentation", "This parameter defines the maximum number of trying to get a buffer (Transmit / Receive), depending of the return value of PduR_FrTpProvideTxBuffer / PduR_FrTpProvideRxBuffer and on whether retry is configured."});
        this.addAnnotation((ENamedElement)this.getFlexrayTpChannel_MaxFrIf(), source, new String[]{"documentation", "This parameter defines the maximum number of trying to send a frame when the FrIf returns an error."});
        this.addAnnotation((ENamedElement)this.getFlexrayTpChannel_MaxRetries(), source, new String[]{"documentation", "This parameter defines the maximum number of retries (if retry is configured for the particular channel)."});
        this.addAnnotation((ENamedElement)this.getFlexrayTpChannel_MaximumMessageLength(), source, new String[]{"documentation", "This specifies the maximum message length for the particular channel."});
        this.addAnnotation((ENamedElement)this.getFlexrayTpChannel_MinimumSeparationTime(), source, new String[]{"documentation", "This attribute defines the minimum amount of time (separation Time) between two succeeding CFs. Specified in seconds."});
        this.addAnnotation((ENamedElement)this.getFlexrayTpChannel_MulticastSegmentation(), source, new String[]{"documentation", "This attribute defines whether segmentation within a 1:n connection is allowed or not."});
        this.addAnnotation((ENamedElement)this.getFlexrayTpChannel_PduPools(), source, new String[]{"documentation", "A FlexRayTpChannel contains a pool of NPdus."});
        this.addAnnotation((ENamedElement)this.getFlexrayTpChannel_TimeBr(), source, new String[]{"documentation", "This parameter defines the time in seconds between receiving the last CF of a block or an FF-x (or SF-x) and sending out an FC or AF."});
        this.addAnnotation((ENamedElement)this.getFlexrayTpChannel_TimeBuffer(), source, new String[]{"documentation", "This parameter defines the time in seconds of waiting for the next try (if retry is activated) to get a Tx or Rx buffer."});
        this.addAnnotation((ENamedElement)this.getFlexrayTpChannel_TimeCs(), source, new String[]{"documentation", "This parameter defines the time in seconds between the sending of two consecutive frames or between a  consecutive frame and a flow control (for Transmit Cancellation) or between reception of an flow control or Acknowledgement Frame and sending of the next consecutive frame or a  flow control (for Transmit Cancellation)."});
        this.addAnnotation((ENamedElement)this.getFlexrayTpChannel_TimeFrIf(), source, new String[]{"documentation", "This parameter defines the time in seconds of waiting for the next try (if retry is activated) to send via FrIf_Transmit. Specified in seconds.\r\n\r\n"});
        this.addAnnotation((ENamedElement)this.getFlexrayTpChannel_TimeoutAr(), source, new String[]{"documentation", "This parameter states the timeout in seconds between the PDU transmit request of the Transport Layer to the FlexRay Interface and the corresponding confirmation of the FlexRay Interface on the receiver side (for FC or AF)."});
        this.addAnnotation((ENamedElement)this.getFlexrayTpChannel_TimeoutAs(), source, new String[]{"documentation", "This parameter states the timeout in seconds between the PDU transmit request for the first PDU of the group used in the current connection of the Transport Layer to the FlexRay Interface and the corresponding confirmation of the FlexRay Interface (when having sent the last PDU of the\r\ngroup used in this connection) on the sender side (SF-x, FF-x, CF)."});
        this.addAnnotation((ENamedElement)this.getFlexrayTpChannel_TimeoutBs(), source, new String[]{"documentation", "This parameter defines the timeout in seconds for waiting for an FC or AF on the sender side in a 1:1 connection."});
        this.addAnnotation((ENamedElement)this.getFlexrayTpChannel_TimeoutCr(), source, new String[]{"documentation", "This parameter defines the timeout value in seconds for waiting for a CF or FF-x (in case of retry) after receiving the last CF or after sending an FC or AF on the receiver side."});
        this.addAnnotation((ENamedElement)this.getFlexrayTpChannel_TpConnections(), source, new String[]{"documentation", "Group of connections that can be used in this channel."});
        this.addAnnotation((ENamedElement)this.getFlexrayTpChannel_TransmitCancellation(), source, new String[]{"documentation", "This attribute states whether Transmit Cancellation is supported on this channel."});
        this.addAnnotation((ENamedElement)this.maximumMessageLengthTypeEEnum, source, new String[]{"documentation", "This specifies the maximum message length for the particular channel."});
        this.addAnnotation((ENamedElement)this.maximumMessageLengthTypeEEnum.getELiterals().get(0), source, new String[]{"documentation", "As ISO, but the maximum payload length is limited to 6 byte (SF-I, FF-I, CF). This is necessary to route TP on CAN when using Extended Addressing or Mixed Addressing on CAN."});
        this.addAnnotation((ENamedElement)this.maximumMessageLengthTypeEEnum.getELiterals().get(1), source, new String[]{"documentation", "Up to (2**12)-1 Byte message length (No FF-Ex or SF-E or AF shall be used and recognized)."});
        this.addAnnotation((ENamedElement)this.maximumMessageLengthTypeEEnum.getELiterals().get(2), source, new String[]{"documentation", "SF-E allowed (SF of arbitrary length depending on FrTpPduLength), up to (2**32)-1 byte message length (all FF-x allowed)."});
        this.addAnnotation((ENamedElement)this.flexRayTpConnectionEClass, source, new String[]{"documentation", "A connection within a channel identifies the sender and the receiver of this particular communication.\r\n\r\nThe FlexRayTp module routes a Pdu through this connection. "});
        this.addAnnotation((ENamedElement)this.getFlexRayTpConnection_DirectTpSdu(), source, new String[]{"documentation", "Reference to the IPdu that is segmented by the Transport Protocol. \r\n\r\nThe source address of the transmitted NPdu is determined by the configured source CommunicationConnector.\r\nThe target address of the transmitted NPdu is determined by the configured target CommunicationConnector.\r\n\r\nTo support the low-level routing of NPdu's the NPdu is a specialization of an IPdu. More details can be found in the NPdu class description. Nevertheless the FlexRayTpConnection must not reference a NPdu with this tpSdu reference. "});
        this.addAnnotation((ENamedElement)this.getFlexRayTpConnection_FlowControlPdu(), source, new String[]{"documentation", "Reference to the  Flow Control NPdu.\r\n\r\nThe Flow Control network protocol data unit (FC N_PDU) is identified by the Flow Control protocol control information (FC N_PCI). The Flow Control network protocol data unit (FC N_PDU) instructs a sending network entity to start, stop or resume transmission of CF N_PDUs. The Flow Control network protocol data unit shall be sent by the receiving network layer entity to the sending network layer entity, when ready to receive more data, after correct reception of:\r\n\r\na) First Frame network protocol data unit (FF N_PDU) \r\nb) the last Consecutive Frame network protocol data unit (CF N_PDU) of a block of Consecutive Frames (CF N_PDU) if further Consecutive Frame network protocol data unit (CF N_PDU) need(s) to be sent."});
        this.addAnnotation((ENamedElement)this.getFlexRayTpConnection_Multicast(), source, new String[]{"documentation", "TP address for 1:n connections."});
        this.addAnnotation((ENamedElement)this.getFlexRayTpConnection_ReversedTpSdu(), source, new String[]{"documentation", "Reference to the IPdu that is segmented by the Transport Protocol. \r\n\r\nIf support of both sending and receiving is used, this association references the IPdu used for the additional second direction.\r\n\r\nThe source address of the transmitted NPdu is determined by the configured target CommunicationConnector.\r\n\r\nThe target address of the transmitted NPdu is determined by the configured source CommunicationConnector.\r\n\r\nTo support the low-level routing of NPdu's the NPdu is a specialization of an IPdu. More details can be found in the NPdu class description. Nevertheless the FlexRayTpConnection must not reference a NPdu with this tpSdu reference. "});
        this.addAnnotation((ENamedElement)this.getFlexRayTpConnection_Source(), source, new String[]{"documentation", "The source of the TP connection."});
        this.addAnnotation((ENamedElement)this.getFlexRayTpConnection_Targets(), source, new String[]{"documentation", "The target of the TP connection.\r\n"});
        this.addAnnotation((ENamedElement)this.getFlexRayTpConnection_TransmitPdus(), source, new String[]{"documentation", "Reference to an NPdu (Single Frame, First Frame or Consecutive Frame).\r\n\r\nThe Single Frame network protocol data unit (SF N_PDU) shall be sent out by the sending network entity and can be received by one or multiple receiving network entities.\r\nThe Single Frame (SF N_PDU) shall be sent out to transfer a service data unit that can be transferred via a single service request to the data link layer. This network protocol data unit shall be sent to transfer unsegmented messages.\r\n\r\nThe First Frame network protocol data unit (FF N_PDU) identifies the first network protocol data unit (N_PDU) of a segmented message transmitted by a network sending entity and received by a receiving network entity. \r\n\r\nThe Consecutive Frame network protocol data unit (CF N_PDU) transfers segments (N_Data) of the service data unit message data (&lt;MessageData&gt;). All network protocol data units (N_PDUs) transmitted by the sending entity after the First Frame network protocol data unit (FF N_PDU) shall be encoded as Consecutive Frames network protocol data units (CF N_PDUs)."});
        this.addAnnotation((ENamedElement)this.flexrayTpNodeEClass, source, new String[]{"documentation", "TP Node (Sender or Receiver) provides the TP Address and the connection to the Topology description.\r\n"});
        this.addAnnotation((ENamedElement)this.linTpChannelEClass, source, new String[]{"documentation", "A LinTP channel represents an internal path for the transmission or reception of a Pdu via LinTp and describes the the sender and the receiver of this particular communication.\r\n\r\nThe LinTp module routes a Pdu through the connection channel "});
        this.addAnnotation((ENamedElement)this.getLinTpChannel_DataPdu(), source, new String[]{"documentation", "Reference to an NPdu (Single Frame, First Frame or Consecutive Frame).\r\n\r\nThe Single Frame network protocol data unit (SF N_PDU) shall be sent out by the sending network entity and can be received by one or multiple receiving network entities.\r\nThe Single Frame (SF N_PDU) shall be sent out to transfer a service data unit that can be transferred via a single service request to the data link layer. This network protocol data unit shall be sent to transfer unsegmented messages.\r\n\r\nThe First Frame network protocol data unit (FF N_PDU) identifies the first network protocol data unit (N_PDU) of a segmented message transmitted by a network sending entity and received by a receiving network entity. \r\n\r\nThe Consecutive Frame network protocol data unit (CF N_PDU) transfers segments (N_Data) of the service data unit message data (<MessageData>). All network protocol data units (N_PDUs) transmitted by the sending entity after the First Frame network protocol data unit (FF N_PDU) shall be encoded as Consecutive Frames network protocol data units (CF N_PDUs)."});
        this.addAnnotation((ENamedElement)this.getLinTpChannel_DropNotRequestedNad(), source, new String[]{"documentation", "Configures if TP Frames of not requested LIN-Slaves are dropped or not. "});
        this.addAnnotation((ENamedElement)this.getLinTpChannel_FlowControl(), source, new String[]{"documentation", "Reference to the  Flow Control NPdu.\r\n\r\nThe Flow Control network protocol data unit (FC N_PDU) is identified by the Flow Control protocol control information (FC N_PCI). The Flow Control network protocol data unit (FC N_PDU) instructs a sending network entity to start, stop or resume transmission of CF N_PDUs. The Flow Control network protocol data unit shall be sent by the receiving network layer entity to the sending network layer entity, when ready to receive more data, after correct reception of:\r\n\r\na) First Frame network protocol data unit (FF N_PDU) \r\nb) the last Consecutive Frame network protocol data unit (CF N_PDU) of a block of Consecutive Frames (CF N_PDU) if further Consecutive Frame network protocol data unit (CF N_PDU) need(s) to be sent.\r\n"});
        this.addAnnotation((ENamedElement)this.getLinTpChannel_LinTpNSdu(), source, new String[]{"documentation", "Reference to the IPdu that is segmented by the Transport Protocol. \r\n\r\nTo support the low-level routing of NPdu's the NPdu is a specialization of an IPdu. More details can be found in the NPdu class description. Nevertheless the LinTpChannel must not reference a NPdu with this linTpNSdu reference. "});
        this.addAnnotation((ENamedElement)this.getLinTpChannel_Multicast(), source, new String[]{"documentation", "TP address for 1:n connections. \r\n"});
        this.addAnnotation((ENamedElement)this.getLinTpChannel_Source(), source, new String[]{"documentation", "The source of the TP connection."});
        this.addAnnotation((ENamedElement)this.getLinTpChannel_Targets(), source, new String[]{"documentation", "The target of the TP connection.\r\n"});
        this.addAnnotation((ENamedElement)this.linTpNodeEClass, source, new String[]{"documentation", "TP Node (Sender or Receiver) provides the TP Address and the connection to the Topology description.\r\n"});
        this.addAnnotation((ENamedElement)this.tpChannelEClass, source, new String[]{"documentation", "A Transport Protocol channel. "});
    }

